28	    __gm__ uint8_t* workspace, uint32_t myPe, const RdmaTmpBuffer& tmpBuf, uint32_t syncId, RdmaSession& session)
29	{
30	    session = {};
31	    __gm__ RdmaInfo* info = reinterpret_cast<__gm__ RdmaInfo*>(workspace);
32	    if (!IsWorkspaceHeaderValid(info)) {
33	        return false;
34	    }
35	    switch (info->backend) {
36	#ifdef PTO_RDMA_BACKEND_HNS_1825_SUPPORTED
37	        case RdmaBackend::HNS_1825:
38	            return hns_1825::BuildSession(workspace, myPe, tmpBuf, syncId, session);
39	#endif
40	        default:
41	            return false;
42	    }
43	}
