67	    session.engine = DmaEngine::RDMA;
68	    session.valid = rdmaSession.valid;
69	    session.contextGm = rdmaSession.execCtx.contextGm;
70	    session.tmpBufAddr = rdmaSession.execCtx.tmpBuf.addr;
71	    session.tmpBufSize = rdmaSession.execCtx.tmpBuf.size;
72	    session.syncId = rdmaSession.execCtx.syncId;
73	    session.destRankId = rdmaSession.execCtx.destRankId;
74	    session.qpIdx = rdmaSession.execCtx.qpIdx;
75	    session.rdmaBackend = rdmaSession.execCtx.backend;
76	    session.myPe = rdmaSession.execCtx.myPe;
77	}
78	
79	AICORE inline bool BuildSession(
80	    __gm__ uint8_t* workspace, uint32_t myPe, const RdmaTmpBuffer& tmpBuf, uint32_t syncId, AsyncSession& session)
81	{
82	    RdmaSession rdmaSession{};
83	    const bool valid = BuildSession(workspace, myPe, tmpBuf, syncId, rdmaSession);
84	    StoreSession(rdmaSession, session);
85	    session.valid = valid;
86	    return valid;
87	}
