89	AICORE inline bool BuildSession(
90	    __gm__ uint8_t* workspace, uint32_t destRankId, uint32_t myPe, const RdmaTmpBuffer& tmpBuf, uint32_t syncId,
91	    AsyncSession& session)
92	{
93	    RdmaSession rdmaSession{};
