100	AICORE inline RdmaExecContext MakeExecContext(const AsyncSession& session, uint32_t peer)
101	{
102	    RdmaExecContext ctx{};
103	    ctx.contextGm = session.contextGm;
104	    ctx.backend = session.rdmaBackend;
105	    ctx.destRankId = peer;
106	    ctx.qpIdx = session.qpIdx;
107	    ctx.myPe = session.myPe;
108	    ctx.tmpBuf = {session.tmpBufAddr, session.tmpBufSize};
109	    ctx.syncId = session.syncId;
110	    return ctx;
111	}
112	
113	AICORE inline RdmaEventContext MakeEventContext(const AsyncSession& session)
114	{
115	    RdmaEventContext ctx{};
116	    ctx.contextGm = session.contextGm;
117	    ctx.backend = session.rdmaBackend;
118	    ctx.tmpBuf = {session.tmpBufAddr, session.tmpBufSize};
119	    ctx.syncId = session.syncId;
120	    return ctx;
121	}
122	
123	AICORE inline uint64_t Write(const RdmaExecContext& ctx, __gm__ uint8_t* dst, __gm__ uint8_t* src, uint64_t len)
124	{
125	    switch (ctx.backend) {
126	#ifdef PTO_RDMA_BACKEND_HNS_1825_SUPPORTED
