148	    const RdmaExecContext& ctx, __gm__ uint8_t* dst, __gm__ uint8_t* src, uint64_t len, __gm__ int32_t* remoteSignal,
149	    int32_t signalValue)
150	{
151	    switch (ctx.backend) {
152	#ifdef PTO_RDMA_BACKEND_HNS_1825_SUPPORTED
