10	
11	// HNS_1825 (Hi1825) RoCE RDMA device-side backend for A5.
12	//
13	// Posts RDMA WRITE / READ from AIV using the RdmaInfo table supplied via RdmaExecContext.
14	// WQE/CQE staging uses the RDMA session's UB scratch; atomics are not supported.
15	
16	#ifndef PTO_COMM_ASYNC_RDMA_BACKENDS_HNS_1825_BACKEND_HPP
17	#define PTO_COMM_ASYNC_RDMA_BACKENDS_HNS_1825_BACKEND_HPP
18	
19	#include "pto/pto-inst.hpp"
20	#include "pto/comm/async_common/async_types.hpp"
21	#include "pto/comm/async/rdma/rdma_device_common.hpp"
22	#include "pto/comm/async/rdma/backends/hns_1825/hns_1825_types.hpp"
23	// AscendC::GetSystemCycle only — do NOT include full kernel_operator.h here.
24	// That pulls adv_api/hccl (`using namespace HcclApi`) and collides with ST
25	// common.hpp symbols (MAX_CC_TILING_NUM / GROUP_NAME_SIZE / ALG_CONFIG_SIZE).
26	#if !defined(__CPU_SIM) && !defined(__COSTMODEL)
27	#include "kernel_operator_sys_var_intf.h"
28	#endif
29	
30	namespace pto {
31	namespace comm {
32	namespace rdma {
33	namespace hns_1825 {
34	namespace detail {
35	
36	constexpr uint32_t kCqeReadSize = sizeof(Hns1825Cqe);
37	
38	struct PostSendResult {
39	    uint32_t curHead;
40	    uint32_t status;
41	};
42	
43	// NIC consumes big-endian; AscendC is little-endian. SQ/CQ head-tail mirrors stay host-order;
44	// only NIC-visible payloads (WQE dwords / software doorbell) are byte-swapped.
45	AICORE inline uint16_t Htobe16(uint16_t v) { return (uint16_t)(((v & 0x00ffU) << 8) | ((v & 0xff00U) >> 8)); }
46	
47	AICORE inline uint32_t Htobe32(uint32_t v)
48	{
49	    return ((v & 0x000000ffU) << 24) | ((v & 0x0000ff00U) << 8) | ((v & 0x00ff0000U) >> 8) | ((v & 0xff000000U) >> 24);
50	}
51	
52	AICORE inline uint64_t Htobe64(uint64_t v)
53	{
54	    return ((v & 0x00000000000000ffULL) << 56) | ((v & 0x000000000000ff00ULL) << 40) |
55	           ((v & 0x0000000000ff0000ULL) << 24) | ((v & 0x00000000ff000000ULL) << 8) |
56	           ((v & 0x000000ff00000000ULL) >> 8) | ((v & 0x0000ff0000000000ULL) >> 24) |
57	           ((v & 0x00ff000000000000ULL) >> 40) | ((v & 0xff00000000000000ULL) >> 56);
58	}
59	
60	// Host-order u32 mirror access (SQ/CQ head-tail): bypass the scalar data cache.
61	AICORE inline uint32_t ReadU32Gm(uint64_t addr) { return ld_dev((__gm__ uint32_t*)addr, 0); }
62	
63	AICORE inline void WriteU32Gm(uint64_t addr, uint32_t value) { st_dev(value, (__gm__ uint32_t*)addr, 0); }
64	
65	// Order scalar UB writes before MTE3 copies a NIC-visible record (WQE / software doorbell) to GM, then order the
66	// MTE3 store before the subsequent scalar dcci / st_dev. Post-copy sync MUST be MTE3->Scalar (not MTE3->MTE2):
67	// RoCE consumers are scalar NIC doorbell paths.
68	AICORE inline void WriteUbToGmWithSync(uint64_t gmAddr, __ubuf__ uint8_t* ub, uint32_t size, uint32_t syncId)
69	{
70	    set_flag(PIPE_S, PIPE_MTE3, syncId);
71	    wait_flag(PIPE_S, PIPE_MTE3, syncId);
72	    copy_ubuf_to_gm_align_v2(
73	        reinterpret_cast<__gm__ uint32_t*>(gmAddr), reinterpret_cast<__ubuf__ uint32_t*>(ub), 0, 1, size, 0, 0, 0);
74	    set_flag(PIPE_MTE3, PIPE_S, syncId);
75	    wait_flag(PIPE_MTE3, PIPE_S, syncId);
76	}
