94	// A CQE is ready when its owner bit matches the lap parity from the current consumer index.
95	AICORE inline bool CheckCqeOwner(__ubuf__ Hns1825Cqe* cqe, uint32_t curTail, uint32_t cqRing)
96	{
97	    constexpr uint32_t kOwnerShift = 31; // owner bit at dw1[31]
98	    uint32_t curOwner = ((cqe->owner_id_qpn & (1U << kOwnerShift)) != 0);
99	    uint32_t expectOwner = (uint32_t)(((curTail & cqRing) == 0));
100	    return (expectOwner ^ curOwner) != 0;
101	}
