103	// CQ doorbell: keep host-order CI mirrors in CQ/SQ tail records, publish big-endian CI to CQ software doorbell.
104	AICORE inline void RingCqDoorbell(
105	    __gm__ RdmaInfo* info, uint32_t pe, uint32_t qpIdx, uint32_t curTail, __ubuf__ uint8_t* ub, uint32_t syncId)
106	{
107	    constexpr uint32_t kCqUpdateCiMask = 0xffffff; // CQ consumer index is 24-bit
108	    uint32_t qpNum = info->qpNum;
109	    __gm__ RoceCqCtx* cqCtx = (__gm__ RoceCqCtx*)(info->scqPtr + ((uint64_t)pe * qpNum + qpIdx) * sizeof(RoceCqCtx));
110	    __gm__ RoceSqCtx* sqCtx = (__gm__ RoceSqCtx*)(info->sqPtr + ((uint64_t)pe * qpNum + qpIdx) * sizeof(RoceSqCtx));
111	
112	    WriteU32Gm(cqCtx->tailAddr, curTail);
113	    WriteU32Gm(sqCtx->tailAddr, curTail);
114	
115	    *reinterpret_cast<__ubuf__ uint32_t*>(ub) = Htobe32(curTail & kCqUpdateCiMask);
116	    WriteUbToGmWithSync(cqCtx->dbSwAddr, ub, sizeof(uint32_t), syncId);
117	    dcci((__gm__ void*)cqCtx->dbSwAddr, SINGLE_CACHE_LINE);
118	}
