120	// Poll until the CQ consumer index reaches targetIdx, or return non-zero status on error/timeout.
121	// Timeout is wall-clock based on AscendC::GetSystemCycle
122	// (A5: us = cycles/1000; A2/A3: us = cycles/50 — see kHns1825CycleToTimeBase).
123	// On timeout do NOT ring the CQ doorbell — the consumer index did not advance.
124	AICORE inline uint32_t PollCq(
125	    __gm__ RdmaInfo* info, uint32_t pe, uint32_t qpIdx, uint32_t targetIdx, __ubuf__ uint8_t* ub, uint32_t syncId)
126	{
127	    constexpr uint32_t kCqeOpcodeShift = 27;
128	    constexpr uint32_t kCqeOpcodeMask = 0x1f;
129	    constexpr uint32_t kCqeOptypeError = 0x1e;
130	    constexpr uint32_t kCqeOptypeInvalid = 0x1f;
131	
132	    if (targetIdx == 0) {
133	        return 0;
134	    }
135	    uint32_t qpNum = info->qpNum;
136	    __gm__ RoceCqCtx* cqCtx = (__gm__ RoceCqCtx*)(info->scqPtr + ((uint64_t)pe * qpNum + qpIdx) * sizeof(RoceCqCtx));
137	
138	    uint32_t cqeSize = cqCtx->cqeSize == 0 ? kHns1825DefaultCqeSize : cqCtx->cqeSize;
139	    uint32_t cqRing = cqCtx->depth;
140	    uint32_t curTail = ReadU32Gm(cqCtx->tailAddr);
141	    // A later event may already have advanced the shared CQ beyond this
142	    // target. Monotonic 32-bit indices are unambiguous while outstanding work
143	    // stays below 2^31, which is guaranteed by the much smaller SQ depth.
144	    if (static_cast<int32_t>(curTail - targetIdx) >= 0) {
145	        return 0;
146	    }
147	    const uint32_t startTail = curTail;
148	    uint32_t status = 0;
149	
150	    while (curTail != targetIdx) {
151	        __gm__ uint8_t* cqeAddr = (__gm__ uint8_t*)(cqCtx->bufAddr + (uint64_t)(curTail & (cqRing - 1)) * cqeSize);
152	        __ubuf__ Hns1825Cqe* cqe = (__ubuf__ Hns1825Cqe*)(__ubuf__ void*)ub;
153	        uint32_t cqeType = kCqeOptypeInvalid;
154	        const uint64_t startCycles = static_cast<uint64_t>(AscendC::GetSystemCycle());
155	        bool cqeReady = false;
156	
157	        while (!cqeReady &&
158	               static_cast<uint64_t>(AscendC::GetSystemCycle()) - startCycles < kHns1825PollCqTimeoutCycles) {
159	            dcci((__gm__ void*)cqeAddr, SINGLE_CACHE_LINE);
160	            ReadGmToUb(ub, (uint64_t)cqeAddr, kCqeReadSize, syncId);
161	            cqeType = (cqe->op_sr_wqebb >> kCqeOpcodeShift) & kCqeOpcodeMask;
162	            cqeReady = cqeType != kCqeOptypeInvalid && CheckCqeOwner(cqe, curTail, cqRing);
163	        }
164	        if (!cqeReady) {
165	            status = kHns1825PollCqTimeoutError;
166	            break;
167	        }
168	        if (cqeType == kCqeOptypeError) {
169	            status = cqe->syndrome == 0 ? kHns1825CqeError : cqe->syndrome;
170	            curTail++;
171	            break;
172	        }
173	        curTail++;
174	    }
175	
176	    // Ring doorbell only if the consumer index moved (success or error-CQE consumed).
177	    if (curTail != startTail) {
178	        RingCqDoorbell(info, pe, qpIdx, curTail, ub, syncId);
179	    }
180	    return status;
181	}
