183	// Fill the 16B WQE control segment in the UB staging buffer; returns pointer just after it.
184	AICORE inline __ubuf__ uint8_t* FillWqeCtrlSeg(__ubuf__ uint8_t* ubBase, uint32_t curHead, uint32_t depth)
185	{
186	    constexpr uint32_t kCtrlValue = 0x40;   // owner_sl fixed part
187	    constexpr uint32_t kVaValue = 0x20;     // df_tsl VA bit
188	    constexpr uint32_t kCqeSignalShift = 7; // df_tsl CR bit
189	    constexpr uint32_t kOwnerShift = 7;     // owner_sl owner bit
190	    constexpr uint32_t kCmpTaskLenShift = 28;
191	    constexpr uint32_t kMsnShift = 12;
192	    constexpr uint32_t kMsnMask = 0x3;
193	    constexpr uint32_t kSegLenUnit = sizeof(uint64_t); // section length unit = 8B
194	    constexpr uint32_t kDataSegBdsl = sizeof(Hns1825WqeDataSeg) / kSegLenUnit;
195	    uint16_t wf_bdsl = (uint16_t)(kDataSegBdsl | ((curHead & kMsnMask) << kMsnShift));
196	
197	    __ubuf__ Hns1825WqeCtrlSeg* ctrl = (__ubuf__ Hns1825WqeCtrlSeg*)(__ubuf__ void*)ubBase;
198	    ctrl->owner_sl = (((curHead & depth) == 0) ? 0 : (1U << kOwnerShift)) | kCtrlValue;
199	    ctrl->df_tsl = (uint8_t)((1U << kCqeSignalShift) | kVaValue | (sizeof(Hns1825WqeRdmaTaskSeg) / kSegLenUnit));
200	    ctrl->wf_bdsl = Htobe16(wf_bdsl);
201	    ctrl->cl_pi = Htobe32(1U << kCmpTaskLenShift);
202	    ctrl->db = 0;
203	    return ubBase + sizeof(Hns1825WqeCtrlSeg);
204	}
205	
206	// Inline WRITE uses the bytes after the task segment instead of a data segment.
207	AICORE inline __ubuf__ uint8_t* FillInlineWqeCtrlSeg(__ubuf__ uint8_t* ubBase, uint32_t curHead, uint32_t depth)
208	{
209	    constexpr uint32_t kCtrlValue = 0x40;
210	    constexpr uint32_t kDataInlineShift = 6;
211	    constexpr uint32_t kVaValue = 0x20;
212	    constexpr uint32_t kCqeSignalShift = 7;
213	    constexpr uint32_t kOwnerShift = 7;
214	    constexpr uint32_t kCmpTaskLenShift = 28;
215	    constexpr uint32_t kMsnShift = 12;
216	    constexpr uint32_t kMsnMask = 0x3;
217	    constexpr uint32_t kSegLenUnit = sizeof(uint64_t);
218	    constexpr uint32_t kInlineBytes = sizeof(int32_t);
219	    constexpr uint32_t kInlineBdsl = (kInlineBytes + kSegLenUnit - 1U) / kSegLenUnit;
220	    const uint16_t wfBdsl = static_cast<uint16_t>(kInlineBdsl | ((curHead & kMsnMask) << kMsnShift));
221	
222	    __ubuf__ Hns1825WqeCtrlSeg* ctrl = reinterpret_cast<__ubuf__ Hns1825WqeCtrlSeg*>(ubBase);
223	    ctrl->owner_sl = (((curHead & depth) == 0U) ? 0U : (1U << kOwnerShift)) | kCtrlValue;
224	    ctrl->df_tsl = static_cast<uint8_t>(
225	        (1U << kCqeSignalShift) | (1U << kDataInlineShift) | kVaValue | (sizeof(Hns1825WqeRdmaTaskSeg) / kSegLenUnit));
226	    ctrl->wf_bdsl = Htobe16(wfBdsl);
227	    ctrl->cl_pi = Htobe32(1U << kCmpTaskLenShift);
228	    ctrl->db = 0;
229	    return ubBase + sizeof(Hns1825WqeCtrlSeg);
230	}
