232	// Fill the 32B RDMA task segment (opcode / len / remote VA / rkey / ulp).
233	AICORE inline __ubuf__ uint8_t* FillWqeTaskSeg(
234	    __ubuf__ uint8_t* addr, const RdmaSendWr& wr, RdmaOpcode opcode, bool fence = false)
235	{
236	    constexpr uint32_t kMsgWrite = 0x04;
237	    constexpr uint32_t kMsgRead = 0x08;
238	    constexpr uint32_t kReadLastExtLen = 4;
239	    uint32_t hwOpcode = (opcode == RdmaOpcode::OP_RDMA_READ) ? kMsgRead : kMsgWrite;
240	
241	    __ubuf__ Hns1825WqeRdmaTaskSeg* task = (__ubuf__ Hns1825WqeRdmaTaskSeg*)(__ubuf__ void*)addr;
242	    task->com_tsk.value = 0;
243	    task->com_tsk.bs.signal = 1;
244	    task->com_tsk.bs.fence = fence ? 1U : 0U;
245	    task->com_tsk.bs.opcode = hwOpcode;
246	    task->com_tsk.value = Htobe32(task->com_tsk.value);
247	    task->data_len = Htobe32((uint32_t)wr.message_len);
248	    task->imm_data = 0;
249	    task->dw3.value = 0;
250	    if (opcode == RdmaOpcode::OP_RDMA_READ) {
251	        task->dw3.bs.last_ext_len = kReadLastExtLen;
252	        task->dw3.value = Htobe32(task->dw3.value);
253	    }
254	    task->va = Htobe64((uint64_t)wr.remote_addr);
255	    task->rkey = Htobe32(wr.rkey);
256	    task->ulp = Htobe32(wr.lkey & 0xffffU);
257	    return addr + sizeof(Hns1825WqeRdmaTaskSeg);
258	}
259	
260	// Fill the 16B data segment (single SGE).
261	AICORE inline __ubuf__ uint8_t* FillWqeDataSeg(__ubuf__ uint8_t* addr, const RdmaSendWr& wr)
262	{
263	    constexpr uint32_t kNextSgeInvalid = 1U << 31; // le_key L bit
264	    constexpr uint32_t kLkeyMask = 0x3fffffffU;    // le_key key[29:0]
265	
266	    __ubuf__ Hns1825WqeDataSeg* data = (__ubuf__ Hns1825WqeDataSeg*)(__ubuf__ void*)addr;
267	    data->buf_addr = Htobe64((uint64_t)wr.local_addr);
268	    data->r_len = Htobe32((uint32_t)wr.message_len);
269	    data->le_key = Htobe32((wr.lkey & kLkeyMask) | kNextSgeInvalid);
270	    return addr + sizeof(Hns1825WqeDataSeg);
271	}
