273	// Pre-mark the next WQEBB owner byte as invalid so the NIC stops there until the next WQE is posted.
274	AICORE inline void WriteInvalidWqebb(__gm__ RoceSqCtx* sqCtx, uint32_t idx)
275	{
276	    __gm__ Hns1825WqeCtrlSeg* ctrl = (__gm__ Hns1825WqeCtrlSeg*)GetSendWqe(sqCtx, idx & (sqCtx->depth - 1));
277	    ctrl->owner_sl = ((idx & sqCtx->depth) == 0) ? 0xff : 0x7f;
278	    dcci((__gm__ void*)ctrl, SINGLE_CACHE_LINE);
279	}
280	
281	// Assemble the whole 64B WQE in UB, mark the next WQEBB invalid, then MTE-copy the WQE into the SQ slot.
282	AICORE inline uint32_t FillWqeWriteRead(
283	    const RdmaSendWr& wr, __gm__ RoceSqCtx* sqCtx, __gm__ uint8_t* wqeAddr, uint32_t curHead, RdmaOpcode opcode,
284	    __ubuf__ uint8_t* ub, uint32_t syncId)
285	{
286	    __ubuf__ uint8_t* dataUb = FillWqeTaskSeg(FillWqeCtrlSeg(ub, curHead, sqCtx->depth), wr, opcode);
287	    (void)FillWqeDataSeg(dataUb, wr);
288	    WriteInvalidWqebb(sqCtx, curHead + 1);
289	    WriteUbToGmWithSync((uint64_t)wqeAddr, ub, kHns1825WriteReadWqeSize, syncId);
290	    return kHns1825WriteReadWqeSize;
291	}
