293	// Assemble one fenced 4-byte inline RDMA WRITE. The inline value is payload
294	// data and therefore stays in host byte order; only WQE control fields are
295	// converted to the NIC's big-endian format.
296	AICORE inline void FillWqeInlineSet(
297	    const RdmaSendWr& wr, int32_t signalValue, __gm__ RoceSqCtx* sqCtx, __gm__ uint8_t* wqeAddr, uint32_t curHead,
298	    __ubuf__ uint8_t* ub, uint32_t syncId)
299	{
300	    __ubuf__ uint8_t* inlineData =
301	        FillWqeTaskSeg(FillInlineWqeCtrlSeg(ub, curHead, sqCtx->depth), wr, RdmaOpcode::OP_RDMA_WRITE, true);
302	    *reinterpret_cast<__ubuf__ uint64_t*>(inlineData) = static_cast<uint32_t>(signalValue);
303	    *reinterpret_cast<__ubuf__ uint64_t*>(inlineData + sizeof(uint64_t)) = 0U;
304	    WriteInvalidWqebb(sqCtx, curHead + 1U);
305	    WriteUbToGmWithSync(reinterpret_cast<uint64_t>(wqeAddr), ub, kHns1825WriteReadWqeSize, syncId);
306	}
