308	// Ring the SQ doorbell: update PI mirror, publish software doorbell, write hardware doorbell via st_dev.
309	AICORE inline void RingSqDoorbell(__gm__ RoceSqCtx* sqCtx, uint32_t curHead, __ubuf__ uint8_t* ub, uint32_t syncId)
310	{
311	    constexpr uint32_t kPiHighShift = 8;
312	    constexpr uint32_t kPiFieldShift = 32;
313	    constexpr uint32_t kDbTypeSq = 21;
314	    constexpr uint32_t kSgidIdx = 1;
315	    constexpr uint32_t kCntxSize = 1;
316	    WriteU32Gm(sqCtx->headAddr, curHead);
317	
318	    // Software shadow doorbell (big-endian PI).
319	    *reinterpret_cast<__ubuf__ uint32_t*>(ub) = Htobe32(curHead);
320	    WriteUbToGmWithSync(sqCtx->dbSwAddr, ub, sizeof(uint32_t), syncId);
321	    dcci((__gm__ void*)sqCtx->dbSwAddr, SINGLE_CACHE_LINE);
322	
323	    // Hardware doorbell register: single 64-bit st_dev write.
324	    Hns1825SqDb db;
325	    db.value = 0;
326	    db.bs.c = 0;
327	    db.bs.rsvd0 = 0;
328	    db.bs.cntx_size = kCntxSize;
329	    db.bs.qpn = sqCtx->wqn;
330	    db.bs.sub_type = 0;
331	    db.bs.rsvd1 = 0;
332	    db.bs.pi = 0;
333	    db.bs.sgid_index = kSgidIdx;
334	    db.bs.type = kDbTypeSq;
335	    db.bs.mtu_shift = sqCtx->mtuShift;
336	    db.bs.cos = sqCtx->dbCos;
337	    uint64_t dbValue = db.value | ((((uint64_t)curHead >> kPiHighShift) & 0xffULL) << kPiFieldShift);
338	
339	    st_dev(dbValue, (__gm__ uint64_t*)sqCtx->dbAddr, 0);
340	    pipe_barrier(PIPE_ALL);
341	}
