343	// Post one WRITE/READ WQE and preserve any pre-drain error for the returned event.
344	template <RdmaOpcode OP>
345	AICORE inline PostSendResult PostSendReadWrite(const RdmaExecContext& ctx, RdmaSendWr& wr)
346	{
347	    __gm__ RdmaInfo* info = (__gm__ RdmaInfo*)ctx.contextGm;
348	    uint32_t pe = ctx.destRankId;
349	    uint32_t qpIdx = ctx.qpIdx;
350	    uint32_t qpNum = info->qpNum;
351	    __ubuf__ uint8_t* ub = ctx.tmpBuf.addr;
352	    uint32_t syncId = ctx.syncId;
353	
354	    __gm__ RoceSqCtx* sqCtx = (__gm__ RoceSqCtx*)(info->sqPtr + ((uint64_t)pe * qpNum + qpIdx) * sizeof(RoceSqCtx));
355	    uint32_t depth = sqCtx->depth;
356	    uint32_t curHead = ReadU32Gm(sqCtx->headAddr);
357	    uint32_t curTail = ReadU32Gm(sqCtx->tailAddr);
358	
359	    // Drain CQEs if the SQ is about to be full.
360	    if (curHead - curTail >= depth - kHns1825PollCqThreshold) {
361	        uint32_t ret = PollCq(info, pe, qpIdx, curHead, ub, syncId);
362	        if (ret != 0) {
363	            return {curHead, ret};
364	        }
365	    }
366	
367	    __gm__ RdmaMemInfo* remoteMem = (__gm__ RdmaMemInfo*)(info->memPtr + sizeof(RdmaMemInfo) * pe);
368	    __gm__ RdmaMemInfo* localMem = (__gm__ RdmaMemInfo*)(info->memPtr + sizeof(RdmaMemInfo) * ctx.myPe);
369	    wr.rkey = remoteMem->rkey;
370	    wr.lkey = localMem->lkey;
371	
372	    __gm__ uint8_t* wqeAddr = GetSendWqe(sqCtx, curHead & (sqCtx->depth - 1));
373	    (void)FillWqeWriteRead(wr, sqCtx, wqeAddr, curHead, OP, ub, syncId);
374	    dcci((__gm__ void*)wqeAddr, SINGLE_CACHE_LINE);
375	    curHead++;
376	
377	    RingSqDoorbell(sqCtx, curHead, ub, syncId);
378	    return {curHead, 0};
379	}
380	
381	// Post payload WRITE followed by a fenced inline signal WRITE. Both WQEs are
382	// signaled and consume one WQEBB/CQE each, so the existing head/tail mapping
383	// remains valid. The SQ is published once after both WQEs are complete.
384	AICORE inline PostSendResult PostSendWriteNotify(
385	    const RdmaExecContext& ctx, RdmaSendWr& payloadWr, RdmaSendWr& signalWr, int32_t signalValue)
386	{
387	    __gm__ RdmaInfo* info = reinterpret_cast<__gm__ RdmaInfo*>(ctx.contextGm);
388	    const uint32_t pe = ctx.destRankId;
389	    const uint32_t qpIdx = ctx.qpIdx;
390	    const uint32_t qpNum = info->qpNum;
391	    __ubuf__ uint8_t* ub = ctx.tmpBuf.addr;
392	    const uint32_t syncId = ctx.syncId;
393	
394	    __gm__ RoceSqCtx* sqCtx = reinterpret_cast<__gm__ RoceSqCtx*>(
395	        info->sqPtr + (static_cast<uint64_t>(pe) * qpNum + qpIdx) * sizeof(RoceSqCtx));
396	    const uint32_t depth = sqCtx->depth;
397	    uint32_t curHead = ReadU32Gm(sqCtx->headAddr);
398	    const uint32_t curTail = ReadU32Gm(sqCtx->tailAddr);
399	
400	    // The workspace rejects depths <= the threshold. If the threshold is
401	    // reached, draining all outstanding CQEs leaves room for both WQEs before
402	    // any queue state is modified.
403	    if (curHead - curTail >= depth - kHns1825PollCqThreshold) {
404	        const uint32_t status = PollCq(info, pe, qpIdx, curHead, ub, syncId);
405	        if (status != 0U) {
406	            return {curHead, status};
407	        }
408	    }
409	
410	    __gm__ RdmaMemInfo* remoteMem = reinterpret_cast<__gm__ RdmaMemInfo*>(info->memPtr + sizeof(RdmaMemInfo) * pe);
411	    __gm__ RdmaMemInfo* localMem = reinterpret_cast<__gm__ RdmaMemInfo*>(info->memPtr + sizeof(RdmaMemInfo) * ctx.myPe);
412	    payloadWr.rkey = remoteMem->rkey;
413	    payloadWr.lkey = localMem->lkey;
414	    signalWr.rkey = remoteMem->rkey;
415	    signalWr.lkey = localMem->lkey;
416	
417	    __gm__ uint8_t* payloadWqe = GetSendWqe(sqCtx, curHead & (depth - 1U));
418	    (void)FillWqeWriteRead(payloadWr, sqCtx, payloadWqe, curHead, RdmaOpcode::OP_RDMA_WRITE, ub, syncId);
419	    dcci(reinterpret_cast<__gm__ void*>(payloadWqe), SINGLE_CACHE_LINE);
420	
421	    ++curHead;
422	    __gm__ uint8_t* signalWqe = GetSendWqe(sqCtx, curHead & (depth - 1U));
423	    FillWqeInlineSet(signalWr, signalValue, sqCtx, signalWqe, curHead, ub, syncId);
424	    dcci(reinterpret_cast<__gm__ void*>(signalWqe), SINGLE_CACHE_LINE);
425	
426	    ++curHead;
427	    RingSqDoorbell(sqCtx, curHead, ub, syncId);
428	    return {curHead, 0U};
429	}
