431	AICORE inline bool IsRangeInsideMr(uint64_t address, uint64_t length, __gm__ const RdmaMemInfo* mem)
432	{
433	    if (mem == nullptr || address < mem->addr || length == 0 || length > mem->size) {
434	        return false;
435	    }
436	    return address - mem->addr <= mem->size - length;
437	}
