439	AICORE inline uint32_t ValidateTransfer(
440	    const RdmaExecContext& ctx, uint64_t localAddr, uint64_t remoteAddr, uint64_t len)
441	{
442	    __gm__ RdmaInfo* info = reinterpret_cast<__gm__ RdmaInfo*>(ctx.contextGm);
443	    if (!IsWorkspaceHeaderValid(info) || info->backend != RdmaBackend::HNS_1825 ||
444	        ctx.backend != RdmaBackend::HNS_1825 || ctx.destRankId >= info->rankCount || ctx.myPe >= info->rankCount ||
445	        info->memPtr == 0) {
446	        return kHns1825InvalidContextError;
447	    }
448	    if (len > kHns1825MaxTransferBytes) {
449	        return kHns1825InvalidArgumentError;
450	    }
451	    __gm__ RdmaMemInfo* remoteMem =
452	        reinterpret_cast<__gm__ RdmaMemInfo*>(info->memPtr + sizeof(RdmaMemInfo) * ctx.destRankId);
453	    __gm__ RdmaMemInfo* localMem = reinterpret_cast<__gm__ RdmaMemInfo*>(info->memPtr + sizeof(RdmaMemInfo) * ctx.myPe);
454	    return IsRangeInsideMr(localAddr, len, localMem) && IsRangeInsideMr(remoteAddr, len, remoteMem) ?
455	               0 :
456	               kHns1825InvalidArgumentError;
457	}
458	
459	AICORE inline uint32_t ValidateNotifySignal(const RdmaExecContext& ctx, uint64_t remoteSignalAddr)
460	{
461	    if ((remoteSignalAddr & (alignof(int32_t) - 1U)) != 0U) {
462	        return kHns1825InvalidArgumentError;
463	    }
464	    __gm__ RdmaInfo* info = reinterpret_cast<__gm__ RdmaInfo*>(ctx.contextGm);
465	    __gm__ RdmaMemInfo* remoteMem =
466	        reinterpret_cast<__gm__ RdmaMemInfo*>(info->memPtr + sizeof(RdmaMemInfo) * ctx.destRankId);
467	    return IsRangeInsideMr(remoteSignalAddr, sizeof(int32_t), remoteMem) ? 0U : kHns1825InvalidArgumentError;
468	}
469	
470	} // namespace detail
471	
472	// ============================================================================
473	// HNS1825 entry points consumed by the RDMA device dispatcher.
474	// ============================================================================
475	
476	AICORE inline bool BuildSession(
477	    __gm__ uint8_t* workspace, uint32_t myPe, const RdmaTmpBuffer& tmpBuf, uint32_t syncId, RdmaSession& session)
478	{
479	    session = {};
480	    __gm__ RdmaInfo* info = reinterpret_cast<__gm__ RdmaInfo*>(workspace);
481	    bool valid = IsWorkspaceHeaderValid(info) && info->backend == RdmaBackend::HNS_1825 && tmpBuf.addr != nullptr &&
482	                 tmpBuf.size >= kHns1825WriteReadWqeSize && syncId <= kHns1825MaxSyncId && myPe < info->rankCount &&
483	                 info->sqPtr != 0 && info->scqPtr != 0 && info->memPtr != 0;
484	    if (!valid) {
485	        return false;
486	    }
487	
488	    session.execCtx.contextGm = workspace;
489	    session.execCtx.backend = RdmaBackend::HNS_1825;
490	    session.execCtx.destRankId = 0;
491	    session.execCtx.qpIdx = 0;
492	    session.execCtx.myPe = myPe;
493	    session.execCtx.tmpBuf = tmpBuf;
494	    session.execCtx.syncId = syncId;
495	    session.eventCtx.contextGm = workspace;
496	    session.eventCtx.backend = RdmaBackend::HNS_1825;
497	    session.eventCtx.tmpBuf = tmpBuf;
498	    session.eventCtx.syncId = syncId;
499	    session.valid = true;
500	    return true;
501	}
502	
503	AICORE inline bool BuildSession(
504	    __gm__ uint8_t* workspace, uint32_t destRankId, uint32_t myPe, const RdmaTmpBuffer& tmpBuf, uint32_t syncId,
505	    RdmaSession& session)
506	{
507	    if (!BuildSession(workspace, myPe, tmpBuf, syncId, session)) {
508	        return false;
509	    }
510	
511	    __gm__ RdmaInfo* info = reinterpret_cast<__gm__ RdmaInfo*>(workspace);
512	    bool valid = destRankId < info->rankCount;
513	    if (valid) {
514	        __gm__ RoceCqCtx* cqCtx = reinterpret_cast<__gm__ RoceCqCtx*>(
515	            info->scqPtr + static_cast<uint64_t>(destRankId) * info->qpNum * sizeof(RoceCqCtx));
516	        const uint32_t cqeSize = cqCtx->cqeSize == 0 ? kHns1825DefaultCqeSize : cqCtx->cqeSize;
517	        valid = cqeSize >= sizeof(Hns1825Cqe) && cqeSize <= tmpBuf.size;
518	    }
519	    if (!valid) {
520	        session = {};
521	        return false;
522	    }
523	
524	    session.execCtx.destRankId = destRankId;
525	    return true;
526	}
527	
528	// RDMA WRITE: dst is remote, src is local.
529	AICORE inline uint64_t Write(const RdmaExecContext& ctx, __gm__ uint8_t* dst, __gm__ uint8_t* src, uint64_t len)
530	{
531	    const uint32_t validateStatus =
532	        detail::ValidateTransfer(ctx, reinterpret_cast<uint64_t>(src), reinterpret_cast<uint64_t>(dst), len);
533	    if (validateStatus != 0) {
534	        return EncodeErrorHandle(validateStatus);
535	    }
536	    RdmaSendWr wr = {};
537	    wr.remote_addr = dst;
538	    wr.local_addr = src;
539	    wr.message_len = len;
540	    detail::PostSendResult result = detail::PostSendReadWrite<RdmaOpcode::OP_RDMA_WRITE>(ctx, wr);
541	    return result.status == 0 ? EncodeHandle(ctx.destRankId, result.curHead) : EncodeErrorHandle(result.status);
542	}
543	
544	// RDMA WRITE followed by a fenced 4-byte inline RDMA WRITE to remoteSignal.
545	AICORE inline uint64_t WriteNotify(
546	    const RdmaExecContext& ctx, __gm__ uint8_t* dst, __gm__ uint8_t* src, uint64_t len, __gm__ int32_t* remoteSignal,
547	    int32_t signalValue)
548	{
549	    uint32_t status =
550	        detail::ValidateTransfer(ctx, reinterpret_cast<uint64_t>(src), reinterpret_cast<uint64_t>(dst), len);
551	    if (status == 0U) {
552	        status = detail::ValidateNotifySignal(ctx, reinterpret_cast<uint64_t>(remoteSignal));
553	    }
554	    if (status != 0U) {
555	        return EncodeErrorHandle(status);
556	    }
557	
558	    RdmaSendWr payloadWr{};
559	    payloadWr.remote_addr = dst;
560	    payloadWr.local_addr = src;
561	    payloadWr.message_len = len;
562	    RdmaSendWr signalWr{};
563	    signalWr.remote_addr = reinterpret_cast<__gm__ uint8_t*>(remoteSignal);
564	    signalWr.message_len = sizeof(int32_t);
565	
566	    const detail::PostSendResult result = detail::PostSendWriteNotify(ctx, payloadWr, signalWr, signalValue);
567	    return result.status == 0U ? EncodeHandle(ctx.destRankId, result.curHead) : EncodeErrorHandle(result.status);
568	}
569	
570	// RDMA READ: dst is local, src is remote (remote goes into wr.remote_addr).
571	AICORE inline uint64_t Read(const RdmaExecContext& ctx, __gm__ uint8_t* dst, __gm__ uint8_t* src, uint64_t len)
572	{
573	    const uint32_t validateStatus =
574	        detail::ValidateTransfer(ctx, reinterpret_cast<uint64_t>(dst), reinterpret_cast<uint64_t>(src), len);
575	    if (validateStatus != 0) {
576	        return EncodeErrorHandle(validateStatus);
577	    }
578	    RdmaSendWr wr = {};
579	    wr.remote_addr = src;
580	    wr.local_addr = dst;
581	    wr.message_len = len;
582	    detail::PostSendResult result = detail::PostSendReadWrite<RdmaOpcode::OP_RDMA_READ>(ctx, wr);
583	    return result.status == 0 ? EncodeHandle(ctx.destRankId, result.curHead) : EncodeErrorHandle(result.status);
584	}
585	
586	// Symmetric MR base VA of a peer (device VA), read from the RdmaInfo mem table.
587	// The kernel uses it to compute the remote target address: peerBase + offset.
588	AICORE inline uint64_t PeerMrBaseAddr(__gm__ uint8_t* rdmaWorkspace, uint32_t peer)
589	{
590	    __gm__ RdmaInfo* info = (__gm__ RdmaInfo*)rdmaWorkspace;
591	    if (!IsWorkspaceHeaderValid(info) || info->backend != RdmaBackend::HNS_1825 || peer >= info->rankCount ||
592	        info->memPtr == 0) {
593	        return 0;
594	    }
595	    __gm__ RdmaMemInfo* mem = (__gm__ RdmaMemInfo*)(info->memPtr + sizeof(RdmaMemInfo) * peer);
596	    return mem->addr;
597	}
598	
599	// Blocking completion: poll CQ until WQEs up to curHead complete.
600	// Returns 0 on success, kHns1825PollCqTimeoutError on timeout, or CQE syndrome on error.
601	AICORE inline uint32_t WaitEventStatus(uint64_t handle, const RdmaEventContext& ctx)
602	{
603	    if (handle == 0) {
604	        return 0;
605	    }
606	    if (IsErrorHandle(handle)) {
607	        return static_cast<uint32_t>(handle);
608	    }
609	    uint32_t destRankId = 0;
610	    uint32_t curHead = 0;
611	    DecodeHandle(handle, destRankId, curHead);
612	    __gm__ RdmaInfo* info = (__gm__ RdmaInfo*)ctx.contextGm;
613	    if (!IsWorkspaceHeaderValid(info) || info->backend != RdmaBackend::HNS_1825 ||
614	        ctx.backend != RdmaBackend::HNS_1825) {
615	        return kHns1825InvalidContextError;
616	    }
617	    return detail::PollCq(info, destRankId, /*qpIdx*/ 0, curHead, ctx.tmpBuf.addr, ctx.syncId);
618	}
619	
620	AICORE inline bool WaitEvent(uint64_t handle, const RdmaEventContext& ctx) { return WaitEventStatus(handle, ctx) == 0; }
621	
622	// Non-blocking completion check (read-only peek; does not advance the CQ tail). Returns true if the
623	// transfers up to curHead have completed. Mirrors URMA UrmaTestEvent.
624	AICORE inline bool TestEvent(uint64_t handle, const RdmaEventContext& ctx)
625	{
626	    if (handle == 0) {
627	        return true;
628	    }
629	    if (IsErrorHandle(handle)) {
630	        return true;
631	    }
632	    uint32_t destRankId = 0;
633	    uint32_t curHead = 0;
634	    DecodeHandle(handle, destRankId, curHead);
635	
636	    __gm__ RdmaInfo* info = (__gm__ RdmaInfo*)ctx.contextGm;
637	    uint32_t qpNum = info->qpNum;
638	    __gm__ RoceCqCtx* cqCtx =
639	        (__gm__ RoceCqCtx*)(info->scqPtr + ((uint64_t)destRankId * qpNum + 0) * sizeof(RoceCqCtx));
640	
641	    uint32_t cqeSize = cqCtx->cqeSize == 0 ? kHns1825DefaultCqeSize : cqCtx->cqeSize;
642	    uint32_t cqRing = cqCtx->depth;
643	    uint32_t curTail = detail::ReadU32Gm(cqCtx->tailAddr);
644	    // Already drained to or past the target (a previous Wait or post_send poll advanced the tail).
645	    if (static_cast<int32_t>(curTail - curHead) >= 0) {
646	        return true;
647	    }
648	
649	    // Peek the CQE for the last expected completion (curHead-1) without advancing the tail.
650	    uint32_t lastIdx = curHead - 1;
651	    __gm__ uint8_t* cqeAddr = (__gm__ uint8_t*)(cqCtx->bufAddr + (uint64_t)(lastIdx & (cqRing - 1)) * cqeSize);
652	    // The NIC updates CQ memory asynchronously; invalidate cached CQE data before the one-shot Test read.
653	    dcci((__gm__ void*)cqeAddr, SINGLE_CACHE_LINE);
654	    detail::ReadGmToUb(ctx.tmpBuf.addr, (uint64_t)cqeAddr, detail::kCqeReadSize, ctx.syncId);
655	    __ubuf__ Hns1825Cqe* cqe = (__ubuf__ Hns1825Cqe*)(__ubuf__ void*)ctx.tmpBuf.addr;
656	    constexpr uint32_t kCqeOpcodeShift = 27;
657	    constexpr uint32_t kCqeOpcodeMask = 0x1f;
658	    constexpr uint32_t kCqeOptypeInvalid = 0x1f;
659	    const uint32_t cqeType = (cqe->op_sr_wqebb >> kCqeOpcodeShift) & kCqeOpcodeMask;
660	    return cqeType != kCqeOptypeInvalid && detail::CheckCqeOwner(cqe, lastIdx, cqRing);
661	}
662	
663	} // namespace hns_1825
664	} // namespace rdma
665	} // namespace comm
666	} // namespace pto
667	
668	#endif // PTO_COMM_ASYNC_RDMA_BACKENDS_HNS_1825_BACKEND_HPP
