29	#ifdef PTO_RDMA_SUPPORTED
30	#include "pto/comm/async/rdma/rdma_async_intrin.hpp"
31	#include "pto/comm/async/rdma/rdma_workspace_manager.hpp"
32	#include "backends/rdma_test_backend.hpp"
33	#endif
34	
35	#ifdef PTO_RDMA_SUPPORTED
36	template <typename... Args>
37	static void RdmaTrace(uint32_t caseId, int rankId, Args&&... args)
38	{
39	    if (!pto::comm::rdma::test::BackendVerboseEnabled()) {
40	        return;
41	    }
42	    std::ostringstream os;
43	    os << "[RDMA][" << pto::comm::rdma::RdmaWorkspaceManager::ConfiguredBackendName() << "][case " << caseId
44	       << "][rank " << rankId << "] ";
45	    (os << ... << std::forward<Args>(args));
46	    os << '\n';
47	    const std::string line = os.str();
48	    (void)std::fwrite(line.data(), 1, line.size(), stderr);
49	    std::fflush(stderr);
50	}
51	
52	static uint64_t RdmaElapsedUs(const std::chrono::steady_clock::time_point& start)
53	{
54	    return static_cast<uint64_t>(
55	        std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - start).count());
56	}
57	
58	static std::string RdmaHex(uint64_t value)
59	{
60	    std::ostringstream os;
61	    os << "0x" << std::hex << value;
62	    return os.str();
63	}
64	
65	static uint32_t gRdmaCaseSequence = 0;
66	#endif
67	
68	// ============================================================================
69	// TPUT_ASYNC via RDMA.
70	//
71	// Data plane is a true one-sided remote write posted from AIV: root rank writes
72	// its send buffer into every peer's recv buffer. The symmetric communication
73	// buffer layout matches the URMA test:
74	//   [64 x int32 header][sendBuf: count x T][recvBuf: count x T]
75	// The remote target VA is computed from the peer's registered MR base VA
76	// (PeerMrBaseAddr) plus the recv-region offset.
77	// ============================================================================
78	
79	#ifdef PTO_RDMA_SUPPORTED
80	constexpr uint32_t kRdmaPublicEventWaitError = 0x30000;
81	constexpr uint32_t kRdmaPublicEventTestError = 0x30001;
82	constexpr size_t kRdmaTestDataOffset = 64 * sizeof(int32_t);
83	constexpr size_t kRdmaNotifyCanaryBeforeOffset = sizeof(uint32_t);
84	constexpr size_t kRdmaNotifySignalOffset = 2U * sizeof(uint32_t);
85	constexpr size_t kRdmaNotifyCanaryAfterOffset = 3U * sizeof(uint32_t);
86	constexpr int32_t kRdmaNotifySignalValue = 37;
87	constexpr int32_t kRdmaNotifyCanaryBefore = 0x13572468;
88	constexpr int32_t kRdmaNotifyCanaryAfter = 0x24681357;
89	constexpr uint32_t kRdmaNotifyPollLimit = 10000000U;
90	using RdmaTestShape = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
91	using RdmaTestStride = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
92	using RdmaScratchTile = pto::Tile<pto::TileType::Vec, uint8_t, 1, pto::comm::rdma::kRdmaScratchBytes>;
93	
94	template <typename T>
95	using RdmaTestGlobal = pto::GlobalTensor<T, RdmaTestShape, RdmaTestStride, pto::Layout::ND>;
96	
97	AICORE inline uint32_t CompleteRdmaEvent(
98	    pto::comm::AsyncEvent& event, pto::comm::AsyncSession& session, RdmaCompletionMode completionMode)
99	{
100	    if (completionMode != RdmaCompletionMode::PUBLIC_EVENT_WAIT_TEST) {
101	        return pto::comm::rdma::WaitEventStatus(event.handle, session);
102	    }
103	
104	    // The first Test may legitimately be false. Wait must complete the event,
105	    // and Test must then observe the already-consumed target index as complete.
106	    (void)event.Test(session);
107	    if (!event.Wait(session)) {
108	        return kRdmaPublicEventWaitError;
109	    }
110	    return event.Test(session) ? 0 : kRdmaPublicEventTestError;
111	}
112	
113	AICORE inline uint32_t CompleteRdmaOperation(
114	    pto::comm::AsyncEvent& event, pto::comm::AsyncSession& session, RdmaCompletionMode completionMode)
115	{
116	    return completionMode == RdmaCompletionMode::STATUS_WAIT_EACH ? CompleteRdmaEvent(event, session, completionMode) :
117	                                                                    0;
118	}
119	
120	AICORE inline uint32_t CompleteRdmaPeer(
121	    pto::comm::AsyncEvent& lastEvent, pto::comm::AsyncSession& session, RdmaCompletionMode completionMode,
122	    uint32_t currentStatus)
123	{
124	    if (currentStatus != 0 || completionMode == RdmaCompletionMode::STATUS_WAIT_EACH) {
125	        return currentStatus;
126	    }
127	    return CompleteRdmaEvent(lastEvent, session, completionMode);
128	}
129	
130	struct RdmaCompletionState {
131	    pto::comm::AsyncEvent lastEvent;
132	    uint32_t status{0};
133	};
134	
135	AICORE inline bool BuildRdmaTestSession(
136	    RdmaScratchTile& scratchTile, __gm__ uint8_t* rdmaWorkspace, uint32_t myPeer, pto::comm::AsyncSession& session,
137	    uint32_t syncId, __gm__ uint32_t* deviceStatus)
138	{
139	    if (pto::comm::BuildAsyncSession<pto::comm::DmaEngine::RDMA>(scratchTile, rdmaWorkspace, myPeer, session, syncId)) {
140	        return true;
141	    }
142	    *deviceStatus = pto::comm::rdma::kRdmaSessionBuildError;
143	    pipe_barrier(PIPE_ALL);
144	    return false;
145	}
146	
147	template <typename T, size_t count>
148	AICORE inline uint32_t PostPutOperations(
149	    __gm__ T* sendBuf, uint64_t peerBase, uint32_t targetPeer, int elemOffset, int elemCount, int operationCount,
150	    const RdmaTestShape& shape, const RdmaTestStride& stride, pto::comm::AsyncSession& session,
151	    RdmaCompletionMode completionMode)
152	{
153	    RdmaCompletionState completion;
154	    for (int operation = 0; operation < operationCount; ++operation) {
155	        const int operationOffset = elemOffset + operation * elemCount;
156	        RdmaTestGlobal<T> sendGlobal(sendBuf + operationOffset, shape, stride);
157	        __gm__ T* remoteRecv = reinterpret_cast<__gm__ T*>(peerBase + kRdmaTestDataOffset) + count + operationOffset;
158	        RdmaTestGlobal<T> remoteRecvGlobal(remoteRecv, shape, stride);
159	        completion.lastEvent =
160	            pto::comm::TPUT_ASYNC<pto::comm::DmaEngine::RDMA>(remoteRecvGlobal, sendGlobal, session, targetPeer);
161	        completion.status = CompleteRdmaOperation(completion.lastEvent, session, completionMode);
162	        if (completion.status != 0) {
163	            break;
164	        }
165	    }
166	    return CompleteRdmaPeer(completion.lastEvent, session, completionMode, completion.status);
167	}
168	
169	template <typename T, size_t count>
170	AICORE inline uint32_t PostGetOperations(
171	    __gm__ T* recvBuf, uint64_t peerBase, uint32_t sourcePeer, int elemOffset, int elemCount, int operationCount,
172	    const RdmaTestShape& shape, const RdmaTestStride& stride, pto::comm::AsyncSession& session,
173	    RdmaCompletionMode completionMode)
174	{
175	    RdmaCompletionState completion;
176	    for (int operation = 0; operation < operationCount; ++operation) {
177	        const int operationOffset = elemOffset + operation * elemCount;
178	        __gm__ T* remoteSend = reinterpret_cast<__gm__ T*>(peerBase + kRdmaTestDataOffset) + operationOffset;
179	        __gm__ T* localRecv = recvBuf + static_cast<size_t>(sourcePeer) * count + operationOffset;
180	        RdmaTestGlobal<T> localRecvGlobal(localRecv, shape, stride);
181	        RdmaTestGlobal<T> remoteSendGlobal(remoteSend, shape, stride);
182	        completion.lastEvent =
183	            pto::comm::TGET_ASYNC<pto::comm::DmaEngine::RDMA>(localRecvGlobal, remoteSendGlobal, session, sourcePeer);
184	        completion.status = CompleteRdmaOperation(completion.lastEvent, session, completionMode);
185	        if (completion.status != 0) {
186	            break;
187	        }
188	    }
189	    return CompleteRdmaPeer(completion.lastEvent, session, completionMode, completion.status);
190	}
191	
192	template <typename T, size_t count>
193	AICORE inline void ExecutePutRdma(
194	    __gm__ T* localBuf, int nranks, int myRank, int firstRankId, int rootRank, int elemOffset, int elemCount,
195	    int operationCount, RdmaCompletionMode completionMode, __gm__ uint8_t* rdmaWorkspace, uint32_t syncId)
196	{
197	    __gm__ uint32_t* deviceStatus = reinterpret_cast<__gm__ uint32_t*>(localBuf);
198	    *deviceStatus = 0;
199	    if (myRank != rootRank) {
200	        pipe_barrier(PIPE_ALL);
201	        return;
202	    }
203	    const RdmaTestShape shape(1, 1, 1, 1, elemCount);
204	    const RdmaTestStride stride(elemCount, elemCount, elemCount, elemCount, 1);
205	    __gm__ T* sendBuf = reinterpret_cast<__gm__ T*>(reinterpret_cast<__gm__ uint8_t*>(localBuf) + kRdmaTestDataOffset);
206	    pipe_barrier(PIPE_ALL);
207	
208	    const uint32_t myPeer = static_cast<uint32_t>(myRank - firstRankId);
209	    RdmaScratchTile scratchTile;
210	    TASSIGN(scratchTile, 0x0);
211	    pto::comm::AsyncSession session;
212	    if (!BuildRdmaTestSession(scratchTile, rdmaWorkspace, myPeer, session, syncId, deviceStatus)) {
213	        return;
214	    }
215	    for (uint32_t targetPeer = 0; targetPeer < static_cast<uint32_t>(nranks); ++targetPeer) {
216	        if (targetPeer == myPeer) {
217	            continue;
218	        }
219	        const uint64_t peerBase = pto::comm::rdma::PeerMrBaseAddr(rdmaWorkspace, targetPeer);
220	        const uint32_t completionStatus = PostPutOperations<T, count>(
221	            sendBuf, peerBase, targetPeer, elemOffset, elemCount, operationCount, shape, stride, session,
222	            completionMode);
223	        *deviceStatus = completionStatus;
224	        if (completionStatus != 0) {
225	            break;
226	        }
227	    }
228	    pipe_barrier(PIPE_ALL);
229	}
