315	template <size_t count>
316	[[bisheng::core_ratio(0, 1)]] __global__ AICORE void TPutAsyncNotifyRdmaKernelImpl(
317	    __gm__ int32_t* localBuf, int myRank, int firstRankId, int rootRank, __gm__ uint8_t* rdmaWorkspace, uint32_t syncId)
318	{
319	#ifdef PTO_RDMA_SUPPORTED
320	    __gm__ uint8_t* localBytes = reinterpret_cast<__gm__ uint8_t*>(localBuf);
321	    __gm__ uint32_t* deviceStatus = reinterpret_cast<__gm__ uint32_t*>(localBytes);
322	    __gm__ int32_t* localSignal = reinterpret_cast<__gm__ int32_t*>(localBytes + kRdmaNotifySignalOffset);
323	    __gm__ int32_t* sendBuf = reinterpret_cast<__gm__ int32_t*>(localBytes + kRdmaTestDataOffset);
324	    __gm__ int32_t* recvBuf = sendBuf + count;
325	    *deviceStatus = 0U;
326	
327	    if (myRank != rootRank) {
328	        pto::comm::Signal signal(localSignal);
329	        bool signaled = false;
330	        for (uint32_t poll = 0U; poll < kRdmaNotifyPollLimit; ++poll) {
331	            if (pto::comm::TTEST(signal, kRdmaNotifySignalValue, pto::comm::WaitCmp::EQ)) {
332	                signaled = true;
333	                break;
334	            }
335	        }
336	        if (!signaled) {
337	            *deviceStatus = kRdmaPublicEventWaitError;
338	            pipe_barrier(PIPE_ALL);
339	            return;
340	        }
341	
342	        __asm__ __volatile__("");
343	        dcci(static_cast<__gm__ void*>(0), cache_line_t::ENTIRE_DATA_CACHE);
344	        __asm__ __volatile__("");
345	        for (uint32_t index = 0U; index < count; ++index) {
346	            if (recvBuf[index] != static_cast<int32_t>(index + static_cast<uint32_t>(rootRank) * 10000U)) {
347	                *deviceStatus = kRdmaPublicEventTestError;
348	                pipe_barrier(PIPE_ALL);
349	                return;
350	            }
351	        }
352	        pipe_barrier(PIPE_ALL);
353	        return;
354	    }
355	
356	    const uint32_t myPeer = static_cast<uint32_t>(myRank - firstRankId);
357	    const uint32_t targetPeer = myPeer + 1U;
358	    RdmaScratchTile scratchTile;
359	    TASSIGN(scratchTile, 0x0);
360	    pto::comm::AsyncSession session;
361	    if (!BuildRdmaTestSession(scratchTile, rdmaWorkspace, myPeer, session, syncId, deviceStatus)) {
362	        return;
363	    }
364	
365	    const uint64_t peerBase = pto::comm::rdma::PeerMrBaseAddr(rdmaWorkspace, targetPeer);
366	    const RdmaTestShape shape(1, 1, 1, 1, static_cast<int>(count));
367	    const RdmaTestStride stride(
368	        static_cast<int>(count), static_cast<int>(count), static_cast<int>(count), static_cast<int>(count), 1);
369	    RdmaTestGlobal<int32_t> source(sendBuf, shape, stride);
370	    RdmaTestGlobal<int32_t> destination(
371	        reinterpret_cast<__gm__ int32_t*>(peerBase + kRdmaTestDataOffset) + count, shape, stride);
372	    pto::comm::Signal remoteSignal(reinterpret_cast<__gm__ int32_t*>(peerBase + kRdmaNotifySignalOffset));
373	    pto::comm::AsyncEvent event = pto::comm::TPUT_ASYNC_NOTIFY<pto::comm::DmaEngine::RDMA>(
374	        destination, source, remoteSignal, kRdmaNotifySignalValue, pto::comm::NotifyOp::Set, session, targetPeer);
375	    *deviceStatus = CompleteRdmaEvent(event, session, RdmaCompletionMode::PUBLIC_EVENT_WAIT_TEST);
376	    pipe_barrier(PIPE_ALL);
377	#else
378	    (void)localBuf;
379	    (void)myRank;
380	    (void)firstRankId;
381	    (void)rootRank;
382	    (void)rdmaWorkspace;
383	    (void)syncId;
384	#endif
385	}
