387	static bool AllRanksReady(bool localReady, int nRanks, const char* stage, bool* anyRankNotReady = nullptr)
388	{
389	    if (anyRankNotReady != nullptr) {
390	        *anyRankNotReady = false;
391	    }
392	    uint8_t local = localReady ? 1 : 0;
393	    std::vector<uint8_t> all(static_cast<size_t>(nRanks), 0);
394	    if (CommMpiAllgather(&local, 1, all.data(), 1) != 0) {
395	        std::cerr << "[ERROR] MPI_Allgather failed while agreeing on " << stage << std::endl;
396	        return false;
397	    }
398	    for (int rank = 0; rank < nRanks; ++rank) {
399	        if (all[rank] == 0) {
400	            if (anyRankNotReady != nullptr) {
401	                *anyRankNotReady = true;
402	            }
403	            std::cerr << "[RDMA] rank " << rank << " is not ready at stage: " << stage << std::endl;
404	        }
405	    }
406	    return anyRankNotReady == nullptr ? std::all_of(all.begin(), all.end(), [](uint8_t ready) { return ready != 0; }) :
407	                                        !*anyRankNotReady;
408	}
