410	#ifdef PTO_RDMA_SUPPORTED
411	static pto::comm::rdma::WorkspaceInitResult AgreeOnRdmaPreflight(int nRanks)
412	{
413	    using pto::comm::rdma::WorkspaceInitResult;
414	
415	    const auto localPreflight = pto::comm::rdma::RdmaWorkspaceManager::Preflight();
416	    const uint8_t localCode = static_cast<uint8_t>(localPreflight);
417	    std::vector<uint8_t> allCodes(static_cast<size_t>(nRanks), 0);
418	    if (CommMpiAllgather(&localCode, 1, allCodes.data(), 1) != 0) {
419	        std::cerr << "[ERROR] MPI_Allgather failed while agreeing on RDMA backend selection" << std::endl;
420	        return WorkspaceInitResult::ERROR;
421	    }
422	
423	    const bool allDisabled = std::all_of(allCodes.begin(), allCodes.end(), [](uint8_t value) {
424	        return value == static_cast<uint8_t>(WorkspaceInitResult::DISABLED);
425	    });
426	    const bool allReady = std::all_of(allCodes.begin(), allCodes.end(), [](uint8_t value) {
427	        return value == static_cast<uint8_t>(WorkspaceInitResult::READY);
428	    });
429	    if (allDisabled) {
430	        if (CommMpiRank() == 0) {
431	            std::cerr << "[SKIP] no RDMA backend was compiled into this binary (compiled backend="
432	                      << pto::comm::rdma::RdmaWorkspaceManager::ConfiguredBackendName() << ")" << std::endl;
433	        }
434	        return WorkspaceInitResult::DISABLED;
435	    }
436	    if (!allReady) {
437	        if (CommMpiRank() == 0) {
438	            std::cerr << "[ERROR] inconsistent or unsupported RDMA backend selection across ranks" << std::endl;
439	        }
440	        return WorkspaceInitResult::ERROR;
441	    }
442	    return WorkspaceInitResult::READY;
443	}
