445	// ============================================================================
446	// RdmaTestContext: device, registered communication buffer, and RDMA workspace manager.
447	//
448	// Each case owns a complete backend-channel lifecycle. Reusing the same port
449	// across the suite validates channel destruction followed by reconnection.
450	// ============================================================================
451	struct RdmaTestContext {
452	    int deviceId{-1};
453	    int rankId{-1};
454	    int nRanks{0};
455	    rtStream_t stream{nullptr};
456	    void* devBuf{nullptr};
457	    size_t allocSize{0};
458	    pto::comm::rdma::RdmaWorkspaceManager rdmaMgr;
459	    pto::comm::rdma::test::BackendBootstrap boot;
460	    uint32_t traceId{0};
461	
462	    enum class SetupResult {
463	        READY,
464	        FAILED,
465	        SKIPPED,
466	    };
467	
468	    bool SetupLocalResources(size_t commBytesNeeded)
469	    {
470	        bool localReady = aclrtSetDevice(deviceId) == ACL_SUCCESS;
471	        if (!localReady) {
472	            std::cerr << "[ERROR] aclrtSetDevice(" << deviceId << ") failed" << std::endl;
473	        }
474	        if (localReady && rtStreamCreate(&stream, RT_STREAM_PRIORITY_DEFAULT) != 0) {
475	            std::cerr << "[ERROR] rtStreamCreate failed" << std::endl;
476	            localReady = false;
477	        }
478	        allocSize = commBytesNeeded;
479	        if (localReady &&
480	            (aclrtMalloc(&devBuf, allocSize, ACL_MEM_MALLOC_HUGE_FIRST) != ACL_SUCCESS || devBuf == nullptr)) {
481	            std::cerr << "[ERROR] aclrtMalloc(" << allocSize << ") failed" << std::endl;
482	            localReady = false;
483	        }
484	        if (localReady && aclrtMemset(devBuf, allocSize, 0, allocSize) != ACL_SUCCESS) {
485	            std::cerr << "[ERROR] aclrtMemset failed" << std::endl;
486	            localReady = false;
487	        }
488	        return AllRanksReady(localReady, nRanks, "local ACL resource setup");
489	    }
490	
491	    std::string DescribePeers() const
492	    {
493	        std::ostringstream peers;
494	        for (int peer = 0; peer < nRanks; ++peer) {
495	            if (peer != 0) {
496	                peers << ',';
497	            }
498	            peers << peer << ':' << boot.peerIps[peer] << "/phy" << boot.peerPhyIds[peer] << "/sym"
499	                  << RdmaHex(boot.peerSymAddrs[peer]);
500	        }
501	        return peers.str();
502	    }
503	
504	    SetupResult SetupBootstrap()
505	    {
506	        if (!boot.Init(rankId, nRanks, deviceId, devBuf, AllRanksReady)) {
507	            return boot.skipped ? SetupResult::SKIPPED : SetupResult::FAILED;
508	        }
509	        RdmaTrace(traceId, rankId, "SETUP bootstrap ready basePort=", boot.basePort, " peers=[", DescribePeers(), ']');
510	        return SetupResult::READY;
511	    }
512	
513	    bool ConnectRdma()
514	    {
515	        pto::comm::rdma::WorkspaceConfig config{};
516	        config.rankId = static_cast<uint32_t>(rankId);
517	        config.rankCount = static_cast<uint32_t>(nRanks);
518	        config.phyId = boot.phyId;
519	        config.localIp = boot.peerIps[rankId];
520	        config.basePort = boot.basePort;
521	        config.peerIps = boot.peerIps;
522	        config.peerPhyIds = boot.peerPhyIds;
523	        config.peerSymAddrs = boot.peerSymAddrs;
524	        config.symmetricAddr = devBuf;
525	        config.symmetricSize = allocSize;
526	        const bool localConnected = rdmaMgr.Init(config) == pto::comm::rdma::WorkspaceInitResult::READY;
527	        if (!localConnected) {
528	            std::cerr << "[ERROR] RDMA workspace initialization failed" << std::endl;
529	        }
530	        return AllRanksReady(localConnected, nRanks, "RDMA backend channel initialization");
531	    }
532	
533	    SetupResult Setup(
534	        uint32_t caseId, int rank_id, int n_ranks, int n_devices, int first_device_id, size_t commBytesNeeded)
535	    {
536	        const auto setupStart = std::chrono::steady_clock::now();
537	        traceId = caseId;
538	        rankId = rank_id;
539	        nRanks = n_ranks;
540	        deviceId = rank_id % n_devices + first_device_id;
541	        rdmaMgr.SetTraceId(traceId);
542	        RdmaTrace(traceId, rankId, "SETUP begin device=", deviceId, " commBytes=", commBytesNeeded);
543	        if (!SetupLocalResources(commBytesNeeded)) {
544	            return SetupResult::FAILED;
545	        }
546	        RdmaTrace(
547	            traceId, rankId, "SETUP local resources ready stream=", stream, " devBuf=", devBuf,
548	            " allocSize=", allocSize, " elapsed_us=", RdmaElapsedUs(setupStart));
549	        const SetupResult bootstrapResult = SetupBootstrap();
550	        if (bootstrapResult != SetupResult::READY) {
551	            return bootstrapResult;
552	        }
553	        CommMpiBarrier();
554	        const auto connectStart = std::chrono::steady_clock::now();
555	        if (!ConnectRdma()) {
556	            return SetupResult::FAILED;
557	        }
558	        RdmaTrace(
559	            traceId, rankId, "SETUP RDMA backend ready connect_us=", RdmaElapsedUs(connectStart),
560	            " total_us=", RdmaElapsedUs(setupStart));
561	        return SetupResult::READY;
562	    }
563	
564	    bool Cleanup()
565	    {
566	        const auto cleanupStart = std::chrono::steady_clock::now();
567	        RdmaTrace(traceId, rankId, "CLEANUP begin devBuf=", devBuf, " stream=", stream);
568	        CommMpiBarrier();
569	        bool localOk = rdmaMgr.Finalize();
570	        if (devBuf != nullptr) {
571	            aclError ret = aclrtFree(devBuf);
572	            if (ret != ACL_SUCCESS) {
573	                std::cerr << "[ERROR] aclrtFree(symmetric buffer) failed: " << static_cast<int>(ret) << std::endl;
574	                localOk = false;
575	            } else {
576	                devBuf = nullptr;
577	            }
578	        }
579	        if (stream != nullptr) {
580	            rtError_t ret = rtStreamDestroy(stream);
581	            if (ret != 0) {
582	                std::cerr << "[ERROR] rtStreamDestroy failed: " << ret << std::endl;
583	                localOk = false;
584	            }
585	            stream = nullptr;
586	        }
587	        const bool allOk = AllRanksReady(localOk, nRanks, "RDMA test resource cleanup");
588	        CommMpiBarrier();
589	        RdmaTrace(
590	            traceId, rankId, "CLEANUP end localOk=", localOk, " allOk=", allOk,
591	            " elapsed_us=", RdmaElapsedUs(cleanupStart));
592	        return allOk;
593	    }
594	};
595	#endif // PTO_RDMA_SUPPORTED
