597	template <typename T>
598	static T RdmaInputValue(size_t index, int rankId)
599	{
600	    if constexpr (sizeof(T) == sizeof(uint8_t)) {
601	        return static_cast<T>(((index * 131U) ^ (index >> 8U) ^ (static_cast<size_t>(rankId) * 17U)) & 0xffU);
602	    }
603	    return static_cast<T>(index + static_cast<size_t>(rankId) * 10000U);
604	}
