606	template <typename T>
607	static T RdmaSentinelValue(size_t index)
608	{
609	    if constexpr (sizeof(T) == sizeof(uint8_t)) {
610	        return static_cast<T>((0xa5U ^ (index * 29U) ^ (index >> 8U)) & 0xffU);
611	    }
612	    return static_cast<T>(-1);
613	}
