662	template <typename T>
663	struct RdmaHostStaging {
664	    T* input{nullptr};
665	    T* output{nullptr};
666	
667	    bool Allocate(size_t inputElements, size_t outputElements, int nRanks)
668	    {
669	        bool localOk = aclrtMallocHost(reinterpret_cast<void**>(&input), inputElements * sizeof(T)) == ACL_SUCCESS &&
670	                       input != nullptr;
671	        localOk = (aclrtMallocHost(reinterpret_cast<void**>(&output), outputElements * sizeof(T)) == ACL_SUCCESS &&
672	                   output != nullptr) &&
673	                  localOk;
674	        if (!localOk) {
675	            std::cerr << "[ERROR] aclrtMallocHost failed!" << std::endl;
676	        }
677	        if (AllRanksReady(localOk, nRanks, "host staging allocation")) {
678	            return true;
679	        }
680	        ReleaseLocal();
681	        return false;
682	    }
683	
684	    void ReleaseLocal()
685	    {
686	        if (input != nullptr) {
687	            (void)aclrtFreeHost(input);
688	            input = nullptr;
689	        }
690	        if (output != nullptr) {
691	            (void)aclrtFreeHost(output);
692	            output = nullptr;
693	        }
694	    }
695	
696	    bool Release(int nRanks)
697	    {
698	        bool localOk = true;
699	        if (input != nullptr) {
700	            localOk = aclrtFreeHost(input) == ACL_SUCCESS;
701	            input = nullptr;
702	        }
703	        if (output != nullptr) {
704	            localOk = (aclrtFreeHost(output) == ACL_SUCCESS) && localOk;
705	            output = nullptr;
706	        }
707	        return AllRanksReady(localOk, nRanks, "host staging release");
708	    }
709	};
