722	    RdmaTrace(
723	        config.caseId, config.rankId, "CASE begin op=", operation, " elemSize=", sizeof(T), " count=", count,
724	        " bytes=", count * sizeof(T), " offset=", config.elemOffset, " elemsPerOp=", config.elemCount,
725	        " operations=", config.operationCount, " completion=", RdmaCompletionModeName(config.completionMode));
726	    const bool localPlanValid =
727	        config.elemOffset >= 0 && config.elemCount > 0 && config.operationCount > 0 &&
728	        static_cast<int64_t>(config.elemOffset) + static_cast<int64_t>(config.elemCount) * config.operationCount <=
729	            static_cast<int64_t>(count);
730	    const std::string validationStage = std::string(operation) + " transfer plan validation";
731	    if (!AllRanksReady(localPlanValid, config.nRanks, validationStage.c_str())) {
732	        return RdmaTestResult::FAILED;
733	    }
734	
735	    const auto setupStart = std::chrono::steady_clock::now();
736	    const RdmaTestContext::SetupResult setup = context.Setup(
737	        config.caseId, config.rankId - config.firstRankId, config.nRanks, config.nDevices, config.firstDeviceId,
738	        communicationBytes);
739	    RdmaTrace(
740	        config.caseId, config.rankId, "CASE setup result=", static_cast<int>(setup),
741	        " elapsed_us=", RdmaElapsedUs(setupStart));
742	    if (setup == RdmaTestContext::SetupResult::READY) {
743	        return RdmaTestResult::PASSED;
744	    }
745	    const bool cleanupOk = context.Cleanup();
746	    return cleanupOk && setup == RdmaTestContext::SetupResult::SKIPPED ? RdmaTestResult::SKIPPED :
747	                                                                         RdmaTestResult::FAILED;
748	}
