750	template <bool IsGet, typename T, size_t count>
751	static bool InitializeRdmaBuffers(
752	    const RdmaCaseConfig& config, RdmaTestContext& context, RdmaHostStaging<T>& staging, T*& sendBuffer, T*& recvBuffer)
753	{
754	    const size_t outputElements = IsGet ? static_cast<size_t>(config.nRanks) * count : count;
755	    if (!staging.Allocate(count, outputElements, config.nRanks)) {
756	        return false;
757	    }
758	    for (size_t index = 0; index < count; ++index) {
759	        staging.input[index] = RdmaInputValue<T>(index, config.rankId);
760	    }
761	    for (size_t index = 0; index < outputElements; ++index) {
762	        staging.output[index] = RdmaSentinelValue<T>(index % count);
763	    }
764	
765	    constexpr size_t kDataOffset = 64 * sizeof(int32_t);
766	    sendBuffer = reinterpret_cast<T*>(static_cast<uint8_t*>(context.devBuf) + kDataOffset);
767	    recvBuffer = sendBuffer + count;
768	    bool localOk =
769	        aclrtMemcpy(sendBuffer, count * sizeof(T), staging.input, count * sizeof(T), ACL_MEMCPY_HOST_TO_DEVICE) ==
770	        ACL_SUCCESS;
771	    localOk = (aclrtMemcpy(
772	                   recvBuffer, outputElements * sizeof(T), staging.output, outputElements * sizeof(T),
773	                   ACL_MEMCPY_HOST_TO_DEVICE) == ACL_SUCCESS) &&
774	              localOk;
775	    const uint32_t zero = 0;
776	    localOk =
777	        (aclrtMemcpy(context.devBuf, sizeof(zero), &zero, sizeof(zero), ACL_MEMCPY_HOST_TO_DEVICE) == ACL_SUCCESS) &&
778	        localOk;
779	    const char* stage = IsGet ? "GET input initialization" : "PUT input initialization";
780	    return AllRanksReady(localOk, config.nRanks, stage);
781	}
