839	template <typename T, size_t count>
840	static bool VerifyPutResult(
841	    const RdmaCaseConfig& config, const RdmaTestContext& context, const RdmaHostStaging<T>& staging,
842	    const RdmaKernelResult& kernelResult)
843	{
844	    bool valid = kernelResult.copied && kernelResult.syncResult == 0 && kernelResult.deviceStatus == 0;
845	    const size_t writeBegin = static_cast<size_t>(config.elemOffset);
846	    const size_t writeEnd = writeBegin + static_cast<size_t>(config.elemCount) * config.operationCount;
847	    for (size_t index = 0; index < count && valid; ++index) {
848	        const bool shouldReceive = config.rankId != config.rootRank && index >= writeBegin && index < writeEnd;
849	        const T expected = shouldReceive ? RdmaInputValue<T>(index, config.rootRank) : RdmaSentinelValue<T>(index);
850	        if (staging.output[index] != expected) {
851	            std::cerr << "PUT Rank " << config.rankId << " Device " << context.deviceId << " SyncRet "
852	                      << kernelResult.syncResult << " Index " << index << " Expected: " << static_cast<float>(expected)
853	                      << " Actual: " << static_cast<float>(staging.output[index]) << std::endl;
854	            valid = false;
855	        }
856	    }
857	    return AllRanksReady(valid, config.nRanks, "PUT result verification");
858	}
