862	static bool VerifyGetResult(
863	    const RdmaCaseConfig& config, const RdmaTestContext& context, const RdmaHostStaging<T>& staging,
864	    const RdmaKernelResult& kernelResult)
865	{
866	    bool valid = kernelResult.copied && kernelResult.syncResult == 0 && kernelResult.deviceStatus == 0;
