872	            const bool shouldReceive =
873	                config.rankId == config.rootRank && sourcePeer != rootPeer && index >= readBegin && index < readEnd;
874	            const T expected =
875	                shouldReceive ? RdmaInputValue<T>(index, config.firstRankId + sourcePeer) : RdmaSentinelValue<T>(index);
