925	template <bool IsGet, typename T, size_t count>
926	static RdmaTestResult RunAsyncRdmaRootKernel(
927	    int rank_id, int n_ranks, int n_devices, int first_device_id, int first_rank_id, int root_rank, uint32_t caseId,
928	    int elemOffset, int elemCount, int operationCount, RdmaCompletionMode completionMode)
929	{
930	#ifndef PTO_RDMA_SUPPORTED
931	    return SkipUnsupportedRdmaKernel(
932	        rank_id, n_ranks, n_devices, first_device_id, first_rank_id, root_rank, caseId, elemOffset, elemCount,
933	        operationCount, completionMode);
934	#else
935	    const auto caseStart = std::chrono::steady_clock::now();
936	    const char* operation = IsGet ? "GET" : "PUT";
937	    const RdmaCaseConfig config{rank_id, n_ranks,    n_devices, first_device_id, first_rank_id, root_rank,
938	                                caseId,  elemOffset, elemCount, operationCount,  completionMode};
939	    const size_t recvElements = IsGet ? static_cast<size_t>(n_ranks) * count : count;
940	    const size_t commBytesNeeded = 64 * sizeof(int32_t) + (recvElements + count) * sizeof(T);
941	    RdmaTestContext context;
942	    const RdmaTestResult preparation = PrepareRdmaCase<T, count>(operation, config, commBytesNeeded, context);
943	    if (preparation != RdmaTestResult::PASSED) {
944	        return preparation;
945	    }
946	    RdmaHostStaging<T> staging;
947	    T* sendBuffer = nullptr;
948	    T* recvBuffer = nullptr;
949	    if (!InitializeRdmaBuffers<IsGet, T, count>(config, context, staging, sendBuffer, recvBuffer)) {
950	        return AbortRdmaCase(config, context, staging);
951	    }
952	    if constexpr (IsGet) {
953	#ifdef PTO_RDMA_GET_TEST
954	        const RdmaKernelResult kernelResult =
955	            LaunchGetRdmaKernel<T, count>(config, context, staging.output, recvElements, recvBuffer);
956	        const bool dataValid = VerifyGetResult<T, count>(config, context, staging, kernelResult);
957	        return FinishRdmaCase(operation, config, context, staging, dataValid, caseStart);
958	#endif
959	    } else {
960	        const RdmaKernelResult kernelResult =
961	            LaunchPutRdmaKernel<T, count>(config, context, staging.output, recvBuffer);
962	        const bool dataValid = VerifyPutResult<T, count>(config, context, staging, kernelResult);
963	        return FinishRdmaCase(operation, config, context, staging, dataValid, caseStart);
964	    }
965	    return AbortRdmaCase(config, context, staging);
966	#endif // PTO_RDMA_SUPPORTED
967	}
