979	static RdmaTestResult RunPutAsyncNotifyRdmaSetKernel(
980	    int rankId, int nRanks, int nDevices, int firstDeviceId, int firstRankId, int rootRank, uint32_t caseId)
981	{
982	#ifndef PTO_RDMA_SUPPORTED
983	    return SkipUnsupportedRdmaKernel(rankId, nRanks, nDevices, firstDeviceId, firstRankId, rootRank, caseId);
984	#else
985	    constexpr size_t kCount = 256U;
986	    const auto caseStart = std::chrono::steady_clock::now();
987	    const RdmaCaseConfig config{
988	        rankId,
989	        nRanks,
990	        nDevices,
991	        firstDeviceId,
992	        firstRankId,
993	        rootRank,
994	        caseId,
995	        0,
996	        static_cast<int>(kCount),
997	        1,
998	        RdmaCompletionMode::PUBLIC_EVENT_WAIT_TEST};
999	    const size_t communicationBytes = kRdmaTestDataOffset + 2U * kCount * sizeof(int32_t);
1000	    RdmaTestContext context;
1001	    const RdmaTestResult preparation =
1002	        PrepareRdmaCase<int32_t, kCount>("PUT_NOTIFY", config, communicationBytes, context);
1003	    if (preparation != RdmaTestResult::PASSED) {
1004	        return preparation;
1005	    }
1006	
1007	    RdmaHostStaging<int32_t> staging;
1008	    int32_t* sendBuffer = nullptr;
1009	    int32_t* receiveBuffer = nullptr;
1010	    if (!InitializeRdmaBuffers<false, int32_t, kCount>(config, context, staging, sendBuffer, receiveBuffer)) {
1011	        return AbortRdmaCase(config, context, staging);
1012	    }
1013	
1014	    auto* base = static_cast<uint8_t*>(context.devBuf);
1015	    const int32_t initialSignal = 0;
1016	    bool headerReady =
1017	        aclrtMemcpy(
1018	            base + kRdmaNotifySignalOffset, sizeof(initialSignal), &initialSignal, sizeof(initialSignal),
1019	            ACL_MEMCPY_HOST_TO_DEVICE) == ACL_SUCCESS &&
1020	        aclrtMemcpy(
1021	            base + kRdmaNotifyCanaryBeforeOffset, sizeof(kRdmaNotifyCanaryBefore), &kRdmaNotifyCanaryBefore,
1022	            sizeof(kRdmaNotifyCanaryBefore), ACL_MEMCPY_HOST_TO_DEVICE) == ACL_SUCCESS &&
1023	        aclrtMemcpy(
1024	            base + kRdmaNotifyCanaryAfterOffset, sizeof(kRdmaNotifyCanaryAfter), &kRdmaNotifyCanaryAfter,
1025	            sizeof(kRdmaNotifyCanaryAfter), ACL_MEMCPY_HOST_TO_DEVICE) == ACL_SUCCESS;
1026	    if (!AllRanksReady(headerReady, nRanks, "RDMA notify header initialization")) {
1027	        return AbortRdmaCase(config, context, staging);
1028	    }
1029	
1030	    CommMpiBarrier();
1031	    const auto kernelStart = std::chrono::steady_clock::now();
1032	    // clang-format off
1033	    TPutAsyncNotifyRdmaKernelImpl<kCount><<<1, nullptr, context.stream>>>(
1034	        reinterpret_cast<int32_t*>(context.devBuf), rankId, firstRankId, rootRank,
1035	        reinterpret_cast<uint8_t*>(context.rdmaMgr.GetWorkspaceAddr()), 0U);
1036	    // clang-format on
1037	    const int synchronizeResult = aclrtSynchronizeStream(context.stream);
1038	    const RdmaKernelResult kernelResult = CollectRdmaKernelResult(
1039	        "PUT_NOTIFY", config, context, synchronizeResult, kernelStart, staging.output, kCount, receiveBuffer);
1040	    bool dataValid = VerifyPutResult<int32_t, kCount>(config, context, staging, kernelResult);
1041	
1042	    int32_t signal = 0;
1043	    int32_t canaryBefore = 0;
1044	    int32_t canaryAfter = 0;
1045	    bool notifyValid = aclrtMemcpy(
1046	                           &signal, sizeof(signal), base + kRdmaNotifySignalOffset, sizeof(signal),
1047	                           ACL_MEMCPY_DEVICE_TO_HOST) == ACL_SUCCESS &&
1048	                       aclrtMemcpy(
1049	                           &canaryBefore, sizeof(canaryBefore), base + kRdmaNotifyCanaryBeforeOffset,
1050	                           sizeof(canaryBefore), ACL_MEMCPY_DEVICE_TO_HOST) == ACL_SUCCESS &&
1051	                       aclrtMemcpy(
1052	                           &canaryAfter, sizeof(canaryAfter), base + kRdmaNotifyCanaryAfterOffset, sizeof(canaryAfter),
1053	                           ACL_MEMCPY_DEVICE_TO_HOST) == ACL_SUCCESS;
1054	    const int32_t expectedSignal = rankId == rootRank ? initialSignal : kRdmaNotifySignalValue;
1055	    notifyValid = notifyValid && signal == expectedSignal && canaryBefore == kRdmaNotifyCanaryBefore &&
1056	                  canaryAfter == kRdmaNotifyCanaryAfter;
1057	    if (!notifyValid) {
1058	        std::cerr << "RDMA notify Rank " << rankId << " Device " << context.deviceId << " Signal " << signal
1059	                  << " Expected " << expectedSignal << " CanaryBefore " << canaryBefore << " CanaryAfter "
1060	                  << canaryAfter << std::endl;
1061	    }
1062	    dataValid = AllRanksReady(notifyValid, nRanks, "RDMA notify signal verification") && dataValid;
1063	    return FinishRdmaCase("PUT_NOTIFY", config, context, staging, dataValid, caseStart);
1064	#endif
1065	}
