1098	static RdmaTestResult CheckRdmaDeviceAvailability(int nRanks, int nDevices, int firstDeviceId, int mpiRank)
1099	{
1100	    const int deviceCount = GetAvailableDeviceCount();
1101	    const bool localDevicesReady = deviceCount >= nDevices + firstDeviceId;
1102	    bool anyDeviceMissing = false;
1103	    if (AllRanksReady(localDevicesReady, nRanks, "device availability", &anyDeviceMissing)) {
1104	        return RdmaTestResult::PASSED;
1105	    }
1106	    if (mpiRank == 0) {
1107	        std::cerr << "[SKIP] Need " << (nDevices + firstDeviceId) << " NPU(s), have " << deviceCount << std::endl;
1108	    }
1109	    return anyDeviceMissing ? RdmaTestResult::SKIPPED : RdmaTestResult::FAILED;
1110	}
