1112	static bool InitializeAclForRdma(int nRanks)
1113	{
1114	    constexpr int kAclRepeatInit = 100002;
1115	    const aclError aclRet = aclInit(nullptr);
1116	    const bool aclReady = aclRet == ACL_SUCCESS || static_cast<int>(aclRet) == kAclRepeatInit;
1117	    if (!aclReady) {
1118	        std::cerr << "[ERROR] aclInit failed: " << static_cast<int>(aclRet) << std::endl;
1119	    }
1120	    return AllRanksReady(aclReady, nRanks, "ACL initialization");
1121	}
1122	#endif
