1124	static RdmaLaunchPreparation PrepareRdmaLaunch(int nRanks, int nDevices, int firstDeviceId)
1125	{
1126	    const int mpiRank = CommMpiRank();
1127	    if (!ValidateRdmaLaunchConfiguration(nRanks, nDevices, mpiRank, CommMpiSize())) {
1128	        return {RdmaTestResult::FAILED, mpiRank};
1129	    }
1130	#ifndef PTO_RDMA_SUPPORTED
1131	    (void)firstDeviceId;
1132	    if (mpiRank == 0) {
1133	        std::cerr << "[SKIP] built without PTO_RDMA_SUPPORTED" << std::endl;
1134	    }
1135	    return {RdmaTestResult::SKIPPED, mpiRank};
1136	#else
1137	    const auto preflight = AgreeOnRdmaPreflight(nRanks);
1138	    if (preflight != pto::comm::rdma::WorkspaceInitResult::READY) {
1139	        const RdmaTestResult result = preflight == pto::comm::rdma::WorkspaceInitResult::DISABLED ?
1140	                                          RdmaTestResult::SKIPPED :
1141	                                          RdmaTestResult::FAILED;
1142	        return {result, mpiRank};
1143	    }
1144	    const RdmaTestResult deviceResult = CheckRdmaDeviceAvailability(nRanks, nDevices, firstDeviceId, mpiRank);
1145	    if (deviceResult != RdmaTestResult::PASSED) {
1146	        return {deviceResult, mpiRank};
1147	    }
1148	    return {InitializeAclForRdma(nRanks) ? RdmaTestResult::PASSED : RdmaTestResult::FAILED, mpiRank};
1149	#endif
1150	}
