1160	template <bool IsGet, typename T, size_t count>
1161	static RdmaTestResult RunAsyncRdmaPlan(
1162	    int n_ranks, int n_devices, int first_rank_id, int first_device_id, int elem_offset, int elem_count,
1163	    int operation_count, RdmaCompletionMode completion_mode)
1164	{
1165	    const RdmaLaunchPreparation preparation = PrepareRdmaLaunch(n_ranks, n_devices, first_device_id);
1166	    if (preparation.result != RdmaTestResult::PASSED) {
1167	        return preparation.result;
1168	    }
