    RdmaExecContext execCtx{};
    RdmaEventContext eventCtx{};
    bool valid{false};
};

enum class RdmaOpcode : uint32_t {
    OP_RDMA_READ = 0,
    OP_RDMA_WRITE,
    OP_RDMA_WRITE_WITH_IMM,
};

struct RdmaSge {
    __gm__ uint8_t* addr;
    uint64_t length;
    uint32_t lkey;
};

struct RdmaSendWr {
    uint32_t send_flags;
    uint32_t imm_data;
    __gm__ uint8_t* remote_addr;
    uint32_t rkey;
    __gm__ uint8_t* local_addr;
    uint64_t message_len;
    uint32_t lkey;
};

} // namespace rdma
} // namespace comm
