9	*/
10	
11	// RDMA host control plane. The backend selected at build time determines which
12	// manager creates and releases the underlying resources.
13	
14	#ifndef PTO_COMM_ASYNC_RDMA_WORKSPACE_MANAGER_HPP
15	#define PTO_COMM_ASYNC_RDMA_WORKSPACE_MANAGER_HPP
16	
17	#if defined(__CCE_KT_TEST__)
18	#error "rdma_workspace_manager.hpp is a host-only header and cannot be included in device code."
19	#endif
20	
21	#include <cstdint>
22	#include <iostream>
23	#include <string>
24	#include <vector>
25	
26	#include "pto/comm/rdma_backend.hpp"
27	#ifdef PTO_RDMA_BACKEND_HNS_1825_SUPPORTED
28	#include "pto/comm/async/rdma/backends/hns_1825/hns_1825_arch.hpp"
29	#include "pto/comm/async/rdma/backends/hns_1825/hns_1825_workspace_manager.hpp"
30	#endif
31	
32	namespace pto {
33	namespace comm {
34	namespace rdma {
35	
36	enum class WorkspaceInitResult : uint8_t {
37	    DISABLED = 0,
38	    READY,
39	    ERROR,
40	};
41	
42	struct WorkspaceConfig {
43	    uint32_t rankId{0};
44	    uint32_t rankCount{0};
45	    uint32_t phyId{0};
46	    std::string localIp;
47	    uint16_t basePort{60032};
48	    std::vector<std::string> peerIps;
49	    std::vector<uint32_t> peerPhyIds;
50	    std::vector<uint64_t> peerSymAddrs;
51	    void* symmetricAddr{nullptr};
52	    uint64_t symmetricSize{0};
53	};
54	
55	class RdmaWorkspaceManager {
56	public:
57	    RdmaWorkspaceManager() = default;
58	    ~RdmaWorkspaceManager() = default;
59	
60	    RdmaWorkspaceManager(const RdmaWorkspaceManager&) = delete;
61	    RdmaWorkspaceManager& operator=(const RdmaWorkspaceManager&) = delete;
62	
63	    static RdmaBackend ConfiguredBackend()
64	    {
65	#ifdef PTO_RDMA_BACKEND_HNS_1825_SUPPORTED
66	        return RdmaBackend::HNS_1825;
67	#else
68	        return RdmaBackend::NONE;
69	#endif
70	    }
71	
72	    static const char* ConfiguredBackendName()
73	    {
74	#ifdef PTO_RDMA_BACKEND_HNS_1825_SUPPORTED
75	        return "HNS_1825";
76	#else
77	        return "NONE";
78	#endif
79	    }
80	
81	    static WorkspaceInitResult Preflight()
82	    {
83	        const RdmaBackend backend = ConfiguredBackend();
84	        if (backend == RdmaBackend::NONE) {
85	            return WorkspaceInitResult::DISABLED;
86	        }
87	
88	        switch (backend) {
89	#ifdef PTO_RDMA_BACKEND_HNS_1825_SUPPORTED
90	            case RdmaBackend::HNS_1825: {
91	                const hns_1825::ArchitectureProbe arch = hns_1825::ProbeArchitecture();
92	                if (!arch.supported) {
93	                    std::cerr << "[RDMA] the compiled HNS_1825 backend is only supported on A5; "
94	                                 "current architecture is "
95	                              << hns_1825::DescribeArchitecture(arch) << std::endl;
96	                    return WorkspaceInitResult::ERROR;
97	                }
98	            }
99	                return WorkspaceInitResult::READY;
100	#endif
101	            default:
102	                return WorkspaceInitResult::DISABLED;
103	        }
104	    }
105	
106	    WorkspaceInitResult Init(const WorkspaceConfig& config)
107	    {
108	        (void)config;
109	        const WorkspaceInitResult preflight = Preflight();
110	        if (preflight != WorkspaceInitResult::READY) {
111	            return preflight;
112	        }
113	
114	        switch (ConfiguredBackend()) {
115	#ifdef PTO_RDMA_BACKEND_HNS_1825_SUPPORTED
116	            case RdmaBackend::HNS_1825: {
117	                hns1825Backend_.SetTraceId(traceId_);
118	                const bool initialized = hns1825Backend_.Init(
119	                    config.rankId, config.rankCount, config.phyId, config.localIp, config.basePort, config.peerIps,
120	                    config.peerPhyIds, config.peerSymAddrs, config.symmetricAddr, config.symmetricSize);
121	                activeBackend_ = initialized ? RdmaBackend::HNS_1825 : RdmaBackend::NONE;
122	                return initialized ? WorkspaceInitResult::READY : WorkspaceInitResult::ERROR;
123	            }
124	#endif
125	            default:
126	                return WorkspaceInitResult::DISABLED;
127	        }
128	    }
129	
130	    bool Finalize()
131	    {
132	        bool ok = true;
133	        switch (activeBackend_) {
134	#ifdef PTO_RDMA_BACKEND_HNS_1825_SUPPORTED
135	            case RdmaBackend::HNS_1825:
136	                ok = hns1825Backend_.Finalize();
137	                break;
138	#endif
139	            default:
140	                break;
141	        }
142	        activeBackend_ = RdmaBackend::NONE;
143	        return ok;
144	    }
145	
146	    void SetTraceId(uint32_t traceId) { traceId_ = traceId; }
147	
148	    void* GetWorkspaceAddr() const
