44	
45	// HCOMM-based RoCE control plane for the HNS_1825 backend.
46	//
47	// Flow:
48	//   1. Create the local RoCE endpoint.
49	//   2. Register the symmetric communication buffer.
50	//   3. Create one channel per peer and wait for every channel to become ready.
51	//   4. Read ChannelEntity SQ/CQ/MR metadata and copy RdmaInfo to device memory.
52	//
53	// Teardown releases resources in reverse ownership order: channels, registered
54	// memory, endpoint, then device metadata. The caller supplies peer network and
55	// symmetric-memory metadata; opt-in progress logs use PTO_ROCE_VERBOSE=1.
56	class WorkspaceManager {
57	public:
58	    WorkspaceManager() = default;
59	    ~WorkspaceManager();
60	
61	    WorkspaceManager(const WorkspaceManager&) = delete;
62	    WorkspaceManager& operator=(const WorkspaceManager&) = delete;
63	
64	    void SetTraceId(uint32_t traceId) { traceId_ = traceId; }
65	
66	    // rankId/rankCount     — this PE and the total number of PEs.
67	    // phyId/localIp        — this rank's physical device and RoCE IPv4.
68	    // basePort             — base port for the HCOMM channel handshake.
69	    // peerIps/peerPhyIds   — every rank's RoCE endpoint information.
70	    // peerSymAddrs         — every rank's registered communication-buffer base.
71	    // symmetricAddr/Size   — this rank's symmetric communication buffer.
72	    bool Init(
73	        uint32_t rankId, uint32_t rankCount, uint32_t phyId, const std::string& localIp, uint16_t basePort,
74	        const std::vector<std::string>& peerIps, const std::vector<uint32_t>& peerPhyIds,
75	        const std::vector<uint64_t>& peerSymAddrs, void* symmetricAddr, uint64_t symmetricSize);
76	
77	    static bool Verbose();
78	
79	    // Best-effort teardown. Every owned resource is attempted once, errors are
80	    // accumulated in the return value, and PTO-side handles are always reset.
81	    bool Finalize();
82	
83	    // Device address of the RdmaInfo table passed to the RDMA kernel.
84	    void* GetWorkspaceAddr() const { return rdmaInfoDevice_; }
85	
86	private:
87	    struct DecodedRoceSqContext : host::RoceSqContextSplitDb {
88	        const char* abiName;
89	        uint8_t dbCos;
90	    };
91	
92	    struct RdmaInfoHostLayout {
93	        size_t totalSize{0};
94	        RdmaInfo* info{nullptr};
95	        RoceSqCtx* sq{nullptr};
96	        RoceSqCtx* rq{nullptr};
97	        RoceCqCtx* scq{nullptr};
