#define PTO_COMM_ASYNC_RDMA_BACKENDS_HNS_1825_WORKSPACE_MANAGER_HPP

#if defined(__CCE_KT_TEST__)
#error "hns_1825_workspace_manager.hpp is a host-only header and cannot be included in device code."
