    static_assert(engine == DmaEngine::RDMA, "This overload is for RDMA only");
    rdma::RdmaTmpBuffer tmpBuf{};
    if (!rdma::detail::MakeTmpBufferFromTile(scratchTile, tmpBuf)) {
        session = AsyncSession{};
        return false;
